fn capitalize_first_letter(word: Vec<char>) -> Vec<char> {
    // Clone the input so we can build the output
    let mut result = word.clone();

    // Check the first character.
    // If it's lowercase, replace it with 'A'.
    // If it's already uppercase, leave it as is.
    if result[0].is_ascii_lowercase() {
        result[0] = 'A';
    }

    result
}

